package semester1.practice05.homework;

import java.util.Arrays;
import java.util.Scanner;

final class Homework05 {
    private Homework05() { }
    static void run(int task){ semester1.ConsoleOutput.useUtf8();try(Scanner s=new Scanner(System.in)){switch(task){case 1->sales(s);case 2->inventory();case 3->cinema(s);case 4->dota();case 5->pets(s);default->throw new IllegalArgumentException();}}}
    private static void sales(Scanner s){String[] days={"Понеділок","Вівторок","Середа","Четвер","П'ятниця","Субота","Неділя"};double[] v=new double[7];for(int i=0;i<7;i++){System.out.print(days[i]+" виторг: ");v[i]=Math.max(0,s.nextDouble());}double total=Arrays.stream(v).sum(),avg=total/v.length;int min=0,max=0;for(int i=1;i<v.length;i++){if(v[i]<v[min])min=i;if(v[i]>v[max])max=i;}System.out.printf("Разом %.2f, середнє %.2f%nМаксимум: %s %.2f%nМінімум: %s %.2f%n",total,avg,days[max],v[max],days[min],v[min]);for(int i=0;i<v.length;i++)if(v[i]>avg)System.out.println("Вище середнього: "+days[i]);}
    private static void inventory(){String[] items={"Ноутбук","Смартфон","Навушники","Клавіатура","Монітор 27\""};int[] q={8,3,25,4,12};double[] p={28500,19200,1850,3100,9400},values=new double[items.length];double sum=0;int max=0;System.out.println("Товар | К-сть | Ціна | Вартість");for(int i=0;i<items.length;i++){values[i]=q[i]*p[i];sum+=values[i];if(values[i]>values[max])max=i;System.out.printf("%s | %d | %.2f | %.2f%n",items[i],q[i],p[i],values[i]);if(q[i]<5)System.out.println("⚠ УВАГА: терміново замовити "+items[i]);}System.out.printf("Активи складу: %.2f грн%nНайбільший запас у грошах: %s (%.2f грн)%n",sum,items[max],values[max]);}
    private static void cinema(Scanner s){char[][] h=new char[5][6];for(char[] r:h)Arrays.fill(r,'O');int option;do{System.out.println("1 — зал, 2 — бронювання, 3 — каса, 0 — вихід");option=s.nextInt();switch(option){case 1->{System.out.println("    1 2 3 4 5 6");for(int r=0;r<5;r++)System.out.println("Р"+(r+1)+": "+Arrays.toString(h[r]));}case 2->{System.out.print("Ряд (1–5) і місце (1–6): ");int r=s.nextInt()-1,c=s.nextInt()-1;if(r<0||r>=5||c<0||c>=6)System.out.println("Координати поза залом.");else if(h[r][c]=='X')System.out.println("Місце вже зайняте.");else{h[r][c]='X';System.out.println("Місце заброньовано.");}}case 3->{int booked=0;for(char[] r:h)for(char c:r)if(c=='X')booked++;System.out.printf("Зайнято %d/30, каса %.2f грн%n",booked,booked*180.0);}case 0->System.out.println("Зміну закрито.");default->System.out.println("Немає такого пункту.");}}while(option!=0);}
    private static void dota(){String[] heroes={"Pudge","Invoker","Juggernaut","Crystal Maiden","Earthshaker"};int[] k={8,12,10,2,4},d={6,3,2,9,5},a={14,9,8,18,16},gold={14500,21200,24800,9800,12300};int kills=Arrays.stream(k).sum(),goldSum=Arrays.stream(gold).sum(),mvp=0;double best=-1;for(int i=0;i<5;i++){double kda=(double)(k[i]+a[i])/Math.max(1,d[i]);if(kda>best){best=kda;mvp=i;}System.out.printf("%-18s K/D/A %d/%d/%d KDA %.2f KP %.1f%% Net Worth %d%n",heroes[i],k[i],d[i],a[i],kda,kills==0?0:100.0*(k[i]+a[i])/kills,gold[i]);}System.out.println("Командні вбивства: "+kills+", Net Worth: "+goldSum+", MVP: "+heroes[mvp]);}
    private static void pets(Scanner s){String[] names={"Dog","Cat","Dragon","Unicorn","Huge Titanic Cat"};int[] power={15,25,120,350,2000};double[] chance={45,30,15,8,2};String[] inv=new String[8];int[] strength=new int[8];int count=0,coins=300;while(true){System.out.printf("Монети %d | слоти %d/8 | 1 яйце, 2 інвентар, 0 вихід: ",coins,count);int op=s.nextInt();if(op==0)break;if(op==2){for(int i=0;i<count;i++)System.out.println(inv[i]+" (сила "+strength[i]+")");continue;}if(op!=1){System.out.println("Невідома команда.");continue;}if(coins<100){System.out.println("Не вистачає монет.");continue;}if(count==8){System.out.println("Рюкзак заповнений — спершу звільни слот.");continue;}coins-=100;double roll=Math.random()*100,cumulative=0;int pet=names.length-1;for(int i=0;i<chance.length;i++){cumulative+=chance[i];if(roll<cumulative){pet=i;break;}}inv[count]=names[pet];strength[count++]=power[pet];System.out.println("Випав вихованець: "+names[pet]+"; сила "+power[pet]);}int total=Arrays.stream(strength,0,count).sum();System.out.println("Команда: "+Arrays.toString(Arrays.copyOf(inv,count))+" | сумарна сила "+total);}
}
